_VALIDITY_TYPE_ORDINAL: dict[int, str] = {
    0: "VALIDITY_TYPE_INVALID",
    1: "VALIDITY_TYPE_DAY",
    2: "VALIDITY_TYPE_IOC",
    3: "VALIDITY_TYPE_GTD",
    4: "VALIDITY_TYPE_GTE",
}

def _coerce_validity_type(v: object) -> str:
    if isinstance(v, int):
        return _VALIDITY_TYPE_ORDINAL.get(v, str(v))
    return str(v) if not isinstance(v, str) else v

_ValidityTypeStr = Annotated[str, BeforeValidator(_coerce_validity_type)]

